"""36 original OGE exercises, with model answers and educational marking criteria."""
PRECISION_TASKS = [('20p01', 20, 'Биквадратное уравнение', 'Решите уравнение x⁴ − 13x² + 36=0.', 'Положим t=x²≥0. Получаем (t−4)(t−9)=0. Отсюда t=4 или t=9; x=−3, −2, 2, 3.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'algebra', 'повышенный'), ('20p02', 20, 'Биквадратное уравнение', 'Решите уравнение x⁴ − 25x² + 144=0.', 'Положим t=x²≥0. Получаем (t−9)(t−16)=0. Отсюда t=9 или t=16; x=−4, −3, 3, 4.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'algebra', 'повышенный'), ('20p03', 20, 'Биквадратное уравнение', 'Решите уравнение x⁴ − 41x² + 400=0.', 'Положим t=x²≥0. Получаем (t−16)(t−25)=0. Отсюда t=16 или t=25; x=−5, −4, 4, 5.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'algebra', 'повышенный'), ('20p04', 20, 'Система с произведением', 'Решите систему x+y=7, xy=10. Найдите все пары (x;y).', 'Числа x,y — корни t²−7t+10=0=(t−2)(t−5). Ответ: (2;5) и (5;2).', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'algebra', 'повышенный'), ('20p05', 20, 'Система с произведением', 'Решите систему x+y=10, xy=21. Найдите все пары (x;y).', 'Числа x,y — корни t²−10t+21=0=(t−3)(t−7). Ответ: (3;7) и (7;3).', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'algebra', 'повышенный'), ('20p06', 20, 'Система с произведением', 'Решите систему x+y=13, xy=36. Найдите все пары (x;y).', 'Числа x,y — корни t²−13t+36=0=(t−4)(t−9). Ответ: (4;9) и (9;4).', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'algebra', 'повышенный'), ('21p01', 21, 'Два автомобиля', 'Два автомобиля одновременно выехали из одного города в противоположных направлениях со скоростями 60 и 75 км/ч. Через 3 ч между ними стало 405 км. Найдите, насколько дальше уехал второй автомобиль.', 'Расстояния: 60·3=180 км и 75·3=225 км; разность 45 км. Ответ: 45 км.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'motion', 'повышенный'), ('21p02', 21, 'Два автомобиля', 'Два автомобиля одновременно выехали из одного города в противоположных направлениях со скоростями 48 и 72 км/ч. Через 4 ч между ними стало 480 км. Найдите, насколько дальше уехал второй автомобиль.', 'Расстояния: 48·4=192 км и 72·4=288 км; разность 96 км. Ответ: 96 км.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'motion', 'повышенный'), ('21p03', 21, 'Совместная работа', 'Одна бригада выполняет заказ за 6 дней, вторая — за 10 дней. За какое время они выполнят заказ вместе?', 'За день бригады выполняют 1/6 + 1/10 = 16/60 работы. Время 60/16 = 15/4 дня.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'motion', 'повышенный'), ('21p04', 21, 'Совместная работа', 'Одна бригада выполняет заказ за 8 дней, вторая — за 12 дней. За какое время они выполнят заказ вместе?', 'За день бригады выполняют 1/8 + 1/12 = 20/96 работы. Время 96/20 = 24/5 дня.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'motion', 'повышенный'), ('21p05', 21, 'Смешивание растворов', 'Смешали 20 кг 10%-го раствора и 20 кг 30%-го раствора одного вещества. Найдите процентную концентрацию полученной смеси.', 'Масса вещества: 20·10/100 + 20·30/100 = 8 кг; общая масса 40 кг. Концентрация 20%.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'motion', 'повышенный'), ('21p06', 21, 'Смешивание растворов', 'Смешали 30 кг 20%-го раствора и 30 кг 40%-го раствора одного вещества. Найдите процентную концентрацию полученной смеси.', 'Масса вещества: 30·20/100 + 30·40/100 = 18 кг; общая масса 60 кг. Концентрация 30%.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'motion', 'повышенный'), ('22p01', 22, 'Касание прямой к параболе', 'Для каких значений m прямая y=m имеет ровно одну общую точку с графиком y=(x−1)²+2?', 'Вершина параболы (1;2). При m=2 горизонтальная прямая касается параболы; ниже пересечений нет, выше две точки. Ответ: m=2.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'graph', 'повышенный'), ('22p02', 22, 'Касание прямой к параболе', 'Для каких значений m прямая y=m имеет ровно одну общую точку с графиком y=(x−2)²+3?', 'Вершина параболы (2;3). При m=3 горизонтальная прямая касается параболы; ниже пересечений нет, выше две точки. Ответ: m=3.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'graph', 'повышенный'), ('22p03', 22, 'Касание прямой к параболе', 'Для каких значений m прямая y=m имеет ровно одну общую точку с графиком y=(x−3)²+5?', 'Вершина параболы (3;5). При m=5 горизонтальная прямая касается параболы; ниже пересечений нет, выше две точки. Ответ: m=5.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'graph', 'повышенный'), ('22p04', 22, 'График с исключённой точкой', 'Постройте график y=(x²−4)/(x−2). При каких m прямая y=m имеет с ним ровно одну общую точку?', 'При x≠2 получаем y=x+2; точка (2;4) исключена. Любая горизонтальная прямая пересекает оставшийся график один раз, кроме m=4. Ответ: все m≠4.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'graph', 'повышенный'), ('22p05', 22, 'График с исключённой точкой', 'Постройте график y=(x²−9)/(x−3). При каких m прямая y=m имеет с ним ровно одну общую точку?', 'При x≠3 получаем y=x+3; точка (3;6) исключена. Любая горизонтальная прямая пересекает оставшийся график один раз, кроме m=6. Ответ: все m≠6.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'graph', 'повышенный'), ('22p06', 22, 'График с исключённой точкой', 'Постройте график y=(x²−16)/(x−4). При каких m прямая y=m имеет с ним ровно одну общую точку?', 'При x≠4 получаем y=x+4; точка (4;8) исключена. Любая горизонтальная прямая пересекает оставшийся график один раз, кроме m=8. Ответ: все m≠8.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'graph', 'повышенный'), ('23p01', 23, 'Хорды окружности', 'Хорды AB и CD пересекаются в точке P. Известно AP=6, PB=10, CP=5. Найдите PD.', 'По теореме о пересекающихся хордах AP·PB=CP·PD. Поэтому PD=6·10/5=12.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('23p02', 23, 'Хорды окружности', 'Хорды AB и CD пересекаются в точке P. Известно AP=8, PB=9, CP=6. Найдите PD.', 'По теореме о пересекающихся хордах AP·PB=CP·PD. Поэтому PD=8·9/6=12.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('23p03', 23, 'Хорды окружности', 'Хорды AB и CD пересекаются в точке P. Известно AP=9, PB=12, CP=8. Найдите PD.', 'По теореме о пересекающихся хордах AP·PB=CP·PD. Поэтому PD=9·12/8=27/2.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('23p04', 23, 'Подобие треугольников', 'В треугольнике ABC отрезок DE параллелен BC, D∈AB, E∈AC; AD=4, DB=6, DE=6. Найдите BC.', 'AB=10. Из подобия ADE и ABC следует DE/BC=AD/AB=4/10, поэтому BC=6·10/4=15.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('23p05', 23, 'Подобие треугольников', 'В треугольнике ABC отрезок DE параллелен BC, D∈AB, E∈AC; AD=6, DB=3, DE=10. Найдите BC.', 'AB=9. Из подобия ADE и ABC следует DE/BC=AD/AB=6/9, поэтому BC=10·9/6=15.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('23p06', 23, 'Подобие треугольников', 'В треугольнике ABC отрезок DE параллелен BC, D∈AB, E∈AC; AD=8, DB=4, DE=9. Найдите BC.', 'AB=12. Из подобия ADE и ABC следует DE/BC=AD/AB=8/12, поэтому BC=9·12/8=27/2.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('24p01', 24, 'Медиана к гипотенузе', 'Докажите, что медиана прямоугольного треугольника, проведённая к гипотенузе, равна половине гипотенузы.', 'Пусть угол C прямой, M — середина гипотенузы AB. По теореме Фалеса C лежит на окружности с диаметром AB; её центр M, поэтому MA=MB=MC=AB/2.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('24p02', 24, 'Равные касательные', 'Из точки P вне окружности проведены касательные PA и PB. Докажите, что PA=PB.', 'Соединим центр O с A, B, P. Радиусы OA и OB перпендикулярны касательным. Прямоугольные треугольники OAP и OBP равны по гипотенузе OP и катету OA=OB; PA=PB.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('24p03', 24, 'Свойство средней линии', 'В треугольнике ABC точки M и N — середины AB и AC. Докажите MN∥BC и MN=BC/2.', 'AM/AB=AN/AC=1/2, угол A общий, значит AMN и ABC подобны по двум сторонам и углу между ними. Соответственные углы равны, MN∥BC и MN/BC=1/2.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('24p04', 24, 'Биссектриса ромба', 'Докажите, что диагональ ромба AC делит угол A пополам.', 'В ромбе ABCD: AB=AD и CB=CD, AC — общая сторона. Треугольники ABC и ADC равны по трём сторонам, следовательно ∠BAC=∠CAD.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('24p05', 24, 'Диагонали параллелограмма', 'Докажите, что диагонали параллелограмма делятся точкой пересечения пополам.', 'В параллелограмме ABCD пусть O=AC∩BD. Треугольники ABO и CDO равны по стороне AB=CD и двум прилежащим углам (AB∥CD). Поэтому AO=OC и BO=OD.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('24p06', 24, 'Сумма противоположных углов', 'Докажите, что сумма противоположных углов вписанного четырёхугольника равна 180°.', 'Вписанные углы A и C опираются на две дуги BD, которые вместе дают 360°. Поэтому ∠A+∠C=360°/2=180°. Аналогично ∠B+∠D=180°.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('25p01', 25, 'Высота к гипотенузе', 'Высота CH к гипотенузе AB прямоугольного треугольника ABC делит её на AH=4 и HB=9. Найдите CH и площадь ABC.', 'Из подобия прямоугольных треугольников CH²=AH·HB=36, значит CH=6. AB=13, S=AB·CH/2=39.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('25p02', 25, 'Высота к гипотенузе', 'Высота CH к гипотенузе AB прямоугольного треугольника ABC делит её на AH=9 и HB=16. Найдите CH и площадь ABC.', 'Из подобия прямоугольных треугольников CH²=AH·HB=144, значит CH=12. AB=25, S=AB·CH/2=150.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('25p03', 25, 'Высота к гипотенузе', 'Высота CH к гипотенузе AB прямоугольного треугольника ABC делит её на AH=16 и HB=25. Найдите CH и площадь ABC.', 'Из подобия прямоугольных треугольников CH²=AH·HB=400, значит CH=20. AB=41, S=AB·CH/2=410.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('25p04', 25, 'Площади подобных фигур', 'Треугольники ABC и DEF подобны, причём соответствующая сторона DEF в 2 раза длиннее стороны ABC. Площадь ABC равна 27. Найдите площадь DEF.', 'Площади подобных треугольников относятся как квадраты соответствующих сторон. S_DEF=27·2²=108.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('25p05', 25, 'Площади подобных фигур', 'Треугольники ABC и DEF подобны, причём соответствующая сторона DEF в 3 раза длиннее стороны ABC. Площадь ABC равна 16. Найдите площадь DEF.', 'Площади подобных треугольников относятся как квадраты соответствующих сторон. S_DEF=16·3²=144.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный'), ('25p06', 25, 'Площади подобных фигур', 'Треугольники ABC и DEF подобны, причём соответствующая сторона DEF в 4 раза длиннее стороны ABC. Площадь ABC равна 25. Найдите площадь DEF.', 'Площади подобных треугольников относятся как квадраты соответствующих сторон. S_DEF=25·4²=400.', '2 балла — верное решение с обоснованием всех существенных шагов; 1 балл — верный метод с негрубой вычислительной ошибкой; 0 баллов — решение не обосновано. Учебные критерии.', 'geometry', 'повышенный')]
